import{_ as o,a,b as r}from"./chunks/wired-windows-ipv4.BIKjXuJN.js";import{_ as e,o as d,c as n,aj as s}from"./chunks/framework.Cn87zHeG.js";const P=JSON.parse('{"title":"出厂与跑机测试","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"faq/factory-test.md","filePath":"faq/factory-test.md"}'),i={name:"faq/factory-test.md"};function l(c,t,h,p,q,g){return d(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="出厂与跑机测试" tabindex="-1">出厂与跑机测试 <a class="header-anchor" href="#出厂与跑机测试" aria-label="Permalink to &quot;出厂与跑机测试&quot;">​</a></h1><p><a href="/onerobot-H1/downloads/faq/factory-test-guide.pdf">下载《H1 机器人跑机测试工具使用说明》（PDF）</a></p><blockquote><p>该工具（factory_test）用于机器人出厂 / 交付前的功能验证：浏览器一键触发 SLAM 建图、定位、导航、机械臂老化与跑机压测，并实时反馈接口健康。需固件 <strong>不低于 1.0.026.260525</strong>。</p></blockquote><h2 id="q20" tabindex="-1">Q20. 测试工具怎么访问？ <a class="header-anchor" href="#q20" aria-label="Permalink to &quot;Q20. 测试工具怎么访问？ {#q20}&quot;">​</a></h2><p>与网络配置工具接入方式相同，但<strong>端口为 8090</strong>，且<strong>免登录</strong>（产线内网无鉴权，Chrome / Edge 均可）：</p><table tabindex="0"><thead><tr><th>接入方式</th><th>地址</th></tr></thead><tbody><tr><td>网线直连</td><td><code>http://10.42.0.2:8090</code></td></tr><tr><td>机器人热点</td><td><code>http://192.168.60.1:8090</code></td></tr><tr><td>同一局域网</td><td><code>http://&lt;机器人IP&gt;:8090</code></td></tr></tbody></table><h3 id="wired-direct" tabindex="-1">网线直连：先配置电脑的有线网络 <a class="header-anchor" href="#wired-direct" aria-label="Permalink to &quot;网线直连：先配置电脑的有线网络 {#wired-direct}&quot;">​</a></h3><p>用网线连接电脑与机器人，确认机器人已开机、有线连接已接通，再按电脑系统完成以下设置。<strong>这里修改的是电脑上连接机器人的有线网卡</strong>：电脑使用 <code>10.42.0.1</code>，机器人使用 <code>10.42.0.2</code>，不要把电脑也设置成 <code>10.42.0.2</code>。</p><h4 id="wired-ubuntu" tabindex="-1">Ubuntu <a class="header-anchor" href="#wired-ubuntu" aria-label="Permalink to &quot;Ubuntu {#wired-ubuntu}&quot;">​</a></h4><p>按下图中的 1～5 顺序操作：</p><ol><li>打开「设置」→「网络」。</li><li>在连接机器人的「有线」连接右侧，点击齿轮按钮。</li><li>切换到「IPv4」页签。</li><li>将「IPv4 方式」设为 <strong>「与其他计算机共享」</strong>。</li><li>点击「应用」，再关闭并重新打开该有线连接，使设置生效。</li></ol><p><img src="'+o+'" alt="Ubuntu 有线连接设置：网络 → 有线连接齿轮 → IPv4 → 与其他计算机共享 → 应用"></p><p>重新连接后，在该有线连接的「详细信息」中核对 IPv4 地址。访问 <code>10.42.0.2</code> 时，电脑应位于 <code>10.42.0.0/24</code> 网段，例如 <code>10.42.0.1</code>、子网掩码 <code>255.255.255.0</code>。若共享模式分配到了其他网段，可改选「手动」，填写上述地址和掩码，网关、DNS 留空，再应用并重新连接，用于直连访问机器人页面。</p><h4 id="wired-windows" tabindex="-1">Windows <a class="header-anchor" href="#wired-windows" aria-label="Permalink to &quot;Windows {#wired-windows}&quot;">​</a></h4><ol><li>按 <code>Win + R</code>，输入 <code>ncpa.cpl</code> 并回车，打开「网络连接」。也可以从「控制面板」→「网络和 Internet」→「网络和共享中心」→「更改适配器设置」进入。</li><li>找到<strong>连接机器人的以太网网卡</strong>，右键选择「属性」。选择实际插着网线的物理网卡，不要选择 WLAN 或 VPN 虚拟网卡；名称可能与截图不同。</li></ol><p><img src="'+a+'" alt="Windows 网络连接：右键连接机器人的以太网网卡，选择属性"></p><ol start="3"><li>选中「Internet 协议版本 4（TCP/IPv4）」→「属性」，选择「使用下面的 IP 地址」，填写：</li></ol><table tabindex="0"><thead><tr><th>设置项</th><th>填写内容</th></tr></thead><tbody><tr><td>IP 地址（电脑）</td><td><code>10.42.0.1</code></td></tr><tr><td>子网掩码</td><td><code>255.255.255.0</code></td></tr><tr><td>默认网关</td><td>留空</td></tr><tr><td>首选 / 备用 DNS 服务器</td><td>留空（通过 IP 地址访问机器人页面无需 DNS）</td></tr></tbody></table><ol start="4"><li>点击 IPv4 属性窗口的「确定」，再点击以太网属性窗口的「确定」，保存设置。</li></ol><p><img src="'+r+'" alt="Windows IPv4 属性：电脑 IP 地址为 10.42.0.1，子网掩码为 255.255.255.0，网关与 DNS 留空"></p><p>以上设置用于网线直连。使用机器人热点或同一局域网接入时，按对应方式连接网络即可；有线网卡之后改接普通路由器时，恢复原来的网络设置（通常为自动获取 IP / DNS）。</p><p>配置完成后，在电脑浏览器打开 <a href="http://10.42.0.2:8090" target="_blank" rel="noreferrer">http://10.42.0.2:8090</a>，进入测试工具。若已按上述步骤配置并能打开网络配置工具，无需重复设置电脑 IP，只需将访问端口从 <code>8080</code> 改为 <code>8090</code>。</p><h2 id="q21" tabindex="-1">Q21. 页面顶部的彩色圆点（chip）是什么意思？ <a class="header-anchor" href="#q21" aria-label="Permalink to &quot;Q21. 页面顶部的彩色圆点（chip）是什么意思？ {#q21}&quot;">​</a></h2><p>顶部状态条实时显示各算法/接口话题的健康度：<strong>● 绿 = 正常，● 黄 = 心跳超时（stale），● 红 = 从未收到 / 响应超时</strong>。出现红色 chip 说明对应节点没起来或挂了，请按提示排查，<strong>不要硬测</strong>。</p><h2 id="q22" tabindex="-1">Q22. 怎么建图（SLAM）？ <a class="header-anchor" href="#q22" aria-label="Permalink to &quot;Q22. 怎么建图（SLAM）？ {#q22}&quot;">​</a></h2><ol><li>把机器人放到起点（一般为<strong>充电桩</strong>）。</li><li>「算法测试 → 建图」→ 点 <strong>开始建图</strong>（当前固定从充电桩起点，无需手填位姿）。</li><li>用<strong>遥控器</strong>遥控机器人遍历场地，&quot;实时地图预览&quot;会逐步显示扫描区域。</li><li>扫描完成点 <strong>完成建图</strong>，算法侧自动保存并加载地图。</li></ol><p>⚠️ 建图期间，定位 / 导航 / 机械臂测试会被锁住，要做下一项先点「完成建图」。</p><h2 id="q23" tabindex="-1">Q23. 怎么做定位？ <a class="header-anchor" href="#q23" aria-label="Permalink to &quot;Q23. 怎么做定位？ {#q23}&quot;">​</a></h2><p>需先建好图 → 把机器人放回充电桩（无充电桩原地定位也可）→「算法测试 → 定位」→ <strong>启动定位</strong> → 状态变为 <code>locating_success</code> 即可。定位成功后导航和机械臂测试不会被阻塞。</p><h2 id="q24" tabindex="-1">Q24. 怎么下发导航目标？ <a class="header-anchor" href="#q24" aria-label="Permalink to &quot;Q24. 怎么下发导航目标？ {#q24}&quot;">​</a></h2><p>两种方式二选一：</p><ul><li><strong>预设点（推荐）</strong>：「导航到」一行点 <strong>P1 / P2 / P3</strong> 任一 chip 即下发；灰色 chip 表示未录入，需先录入。</li><li><strong>自定义位姿</strong>：填 <code>x / y / yaw</code>（弧度），按需勾选 <strong>is_accurate_pose</strong>，点 <strong>下发自定义点位</strong>。</li></ul><h2 id="q25" tabindex="-1">Q25. 怎么录入 / 修改预设点 P1/P2/P3？ <a class="header-anchor" href="#q25" aria-label="Permalink to &quot;Q25. 怎么录入 / 修改预设点 P1/P2/P3？ {#q25}&quot;">​</a></h2><p>把机器人开到目标位姿 → 确认定位为 <code>locating_success</code> → 在导航页点 <strong>记录当前点位为 P1 / P2 / P3</strong>。</p><p>⚠️ 录入的预设点<strong>只存内存，测试服务重启后会丢失</strong>并回到默认值。需要永久修改默认点位请联系厂商技术支持。</p><h2 id="q26" tabindex="-1">Q26. 怎么中止正在进行的导航？ <a class="header-anchor" href="#q26" aria-label="Permalink to &quot;Q26. 怎么中止正在进行的导航？ {#q26}&quot;">​</a></h2><p>点导航页的 <strong>取消当前任务</strong>（红色按钮），机器人立即停止；该按钮始终可用。</p><h2 id="q27" tabindex="-1">Q27. 机械臂老化压测怎么做？安全要求是什么？ <a class="header-anchor" href="#q27" aria-label="Permalink to &quot;Q27. 机械臂老化压测怎么做？安全要求是什么？ {#q27}&quot;">​</a></h2><p>填循环次数（默认 3，最少 1）→ 点 <strong>开始测试</strong>，机械臂重复一组动作；中止点 <strong>急停</strong>（任何时候都可点），结束后点 <strong>复位</strong>（运行中不能复位）。</p><p>⚠️ <strong>安全须知</strong>：测试前机器人周围 <strong>2m×2m 无人、无障碍</strong>；建图/定位/导航必须全部停止；若页面急停无效，立即按本体物理急停或断电。</p><h2 id="q28" tabindex="-1">Q28. &quot;跑机压测&quot;是做什么的？ <a class="header-anchor" href="#q28" aria-label="Permalink to &quot;Q28. &quot;跑机压测&quot;是做什么的？ {#q28}&quot;">​</a></h2><p>用于<strong>长时间无人值守</strong>连续跑导航、头部活动和机械臂老化，重点暴露偶发的导航失败、接口异常和老化动作失败。采用&quot;记错继续&quot;策略——单点导航 60 秒未到达等失败会记入错误日志但不中断整轮。</p><p>⚠️ 开始前必须已建好图、定位成功、并在导航页录好点位；过程中机器人会自主移动、机械臂同步运动，现场务必无人靠近。</p><h2 id="q29" tabindex="-1">Q29. 系统诊断页能看什么？出问题怎么把信息给技术支持？ <a class="header-anchor" href="#q29" aria-label="Permalink to &quot;Q29. 系统诊断页能看什么？出问题怎么把信息给技术支持？ {#q29}&quot;">​</a></h2><p>「系统诊断 → 接口健康」列出所有话题的状态、所属组、更新时间和异常详情。遇到无法判断的问题，点 <strong>复制诊断信息</strong> 一键复制全文，连同操作步骤发给厂商技术支持，比口头描述高效得多。</p><h2 id="q30" tabindex="-1">Q30. 怎么预览各路摄像头画面？ <a class="header-anchor" href="#q30" aria-label="Permalink to &quot;Q30. 怎么预览各路摄像头画面？ {#q30}&quot;">​</a></h2><p>「系统诊断 → 摄像头」页可预览头部广角、左/右相机，以及安装了选配件时的头部 D435。实际画面数量和类型以设备配置为准，未安装的选配相机无图不代表故障。</p><p>打开页面时才建立预览订阅；图像传输会占用带宽和处理资源，关闭预览后释放。显示的帧率取决于相机与网络；相机话题和 QoS 见<a href="./../hardware/sensors.html">传感器</a>。</p><h2 id="q31" tabindex="-1">Q31. 怎么下载机器人日志？ <a class="header-anchor" href="#q31" aria-label="Permalink to &quot;Q31. 怎么下载机器人日志？ {#q31}&quot;">​</a></h2><p>「系统诊断 → 接口健康」页点 <strong>打包下载日志</strong>，会把机器人日志目录打成一个 zip 下载，文件名形如 <code>h1_logs_&lt;设备ID&gt;_&lt;时间&gt;.zip</code>。日志较大时进度会短暂停顿，属正常，请耐心等待。</p><h2 id="q32" tabindex="-1">Q32. 怎么录制 ROS Bag 交给研发分析？ <a class="header-anchor" href="#q32" aria-label="Permalink to &quot;Q32. 怎么录制 ROS Bag 交给研发分析？ {#q32}&quot;">​</a></h2><p>「系统诊断 → ROS Bag」页勾选话题（相机/点云等大流量话题单列在红色分组，按需单选）→ 开始录制 → 停止录制 → 在列表里下载（tar 包，解压后可 <code>ros2 bag play</code> 回放）。</p><p>⚠️ 磁盘剩余低于 <strong>2 GiB 会自动停止录制</strong>；bag 很占空间，<strong>用完请立即删除</strong>，避免写满磁盘影响机器人运行。同一时刻只允许一个录制，停止时请耐心等待写入完成，不要断电。</p><h2 id="q33" tabindex="-1">Q33. 执行器硬件测试页能做什么？ <a class="header-anchor" href="#q33" aria-label="Permalink to &quot;Q33. 执行器硬件测试页能做什么？ {#q33}&quot;">​</a></h2><p>「硬件测试 → 执行器」页用于出厂核对升降/头部的限位、堵转和报警，并支持校准与手动微调：</p><ul><li><strong>限位开关</strong>：6 路（升降顶/底、头部俯仰到顶/到底、头部左/右到位），绿=未触发，黄=已到位/撞限位。</li><li><strong>电机告警</strong>：头部堵转（<code>/head/stall</code>）、升降报警（<code>/lift/alarm</code>，附报警码与中文描述）。</li><li><strong>处理堵转/报警</strong>：先停止操作、排除机械卡阻，再到「校准」区点 <strong>清除升降报警</strong>。</li></ul><p>⚠️ 该页会直接驱动升降与头部执行器，操作前确认周围无人、上方及头部运动范围无遮挡。</p>',57)])])}const f=e(i,[["render",l]]);export{P as __pageData,f as default};
